import java.math.*;
import java.util.*;

public class Main {
    record Line(String item, int qty, BigDecimal price, BigDecimal vatRate) {}

    public static void main(String[] args) {
        var lines = List.of(new Line("Keyboard", 2, new BigDecimal("49.99"), new BigDecimal("0.20")));
        System.out.println(lines.get(0).price().multiply(BigDecimal.valueOf(lines.get(0).qty())));
    }
}
